const input = $json.body ?? $json;
const text = String(input.seller_response_text ?? input.response_text ?? input.message ?? "").trim();
const lower = text.toLowerCase();
const dealId = input.deal_id;
const leadId = input.lead_id;
const propertyId = input.property_id;
const dispatchId = input.dispatch_id;
const mao = Number(input.adjusted_mao ?? input.dynamic_mao);
const dnc = input.dnc === true || input.do_not_contact === true;
const blockers = Array.isArray(input.blockers) ? input.blockers : [];

const identityReady = Boolean(dealId && leadId && propertyId && dispatchId);
const hasText = Boolean(text);
const validMao = Number.isFinite(mao) && mao >= 0;
const blocked = dnc || blockers.length > 0;

let classification = "other_response";
let confidence = "medium";
let counteroffer = null;
let nextWorkflow = "WF-338";
let reason = "Seller response requires negotiation-context routing.";

const moneyMatches = text.match(/(?:\$|usd\s*)\s*(\d[\d,]*(?:\.\d{1,2})?)/ig);
if (moneyMatches?.length) {
  const cleaned = moneyMatches[moneyMatches.length - 1].replace(/[^0-9.]/g, "");
  const parsed = Number(cleaned);
  if (Number.isFinite(parsed)) counteroffer = parsed;
}

if (!identityReady || !hasText || !validMao) {
  classification = "incomplete";
  confidence = "low";
  nextWorkflow = "WF-126";
  reason = "Seller response, identity, or dynamic MAO is missing/invalid.";
} else if (blocked) {
  classification = "dnc_or_blocked";
  confidence = "high";
  nextWorkflow = "WF-126";
  reason = "DNC or active blockers prevent further automated negotiation.";
} else if (/(do not contact|don't contact|stop texting|stop calling|remove me|unsubscribe)/i.test(lower)) {
  classification = "dnc";
  confidence = "high";
  nextWorkflow = "WF-126";
  reason = "Seller explicitly requested no further contact.";
} else if (/(yes|sure|okay|ok|deal|accept|accepted|works for me|let's do it|lets do it)/i.test(lower) && !/(but|however|unless|only if)/i.test(lower)) {
  classification = "accepted";
  confidence = "high";
  nextWorkflow = "WF-339";
  reason = "Seller response indicates acceptance without a detected countercondition.";
} else if (counteroffer !== null || /(offer|price|how much|can you do|would you take|come up|too low|more money|higher)/i.test(lower)) {
  classification = counteroffer !== null ? "counteroffer" : "price_question";
  confidence = counteroffer !== null ? "high" : "medium";
  if (counteroffer !== null && counteroffer <= mao) {
    nextWorkflow = "WF-338";
    reason = "Seller counteroffer is at or below dynamic MAO and can proceed through negotiation decision logic.";
  } else if (counteroffer !== null) {
    nextWorkflow = "WF-340";
    reason = "Seller counteroffer exceeds dynamic MAO and requires controlled walk-away/re-engagement logic.";
  } else {
    nextWorkflow = "WF-338";
    reason = "Seller is discussing price and requires negotiation strategy.";
  }
} else if (/(no|no thanks|not interested|pass|decline|declined|can't|cannot|won't|not selling)/i.test(lower)) {
  classification = "rejected";
  confidence = "high";
  nextWorkflow = "WF-340";
  reason = "Seller response indicates rejection or unwillingness to proceed.";
} else if (/(when|where|why|how|what|tell me|question|explain|details)/i.test(lower)) {
  classification = "question";
  confidence = "medium";
  nextWorkflow = "WF-338";
  reason = "Seller has a question requiring negotiation-context response.";
}

const maoRelation = counteroffer === null || !validMao
  ? "unknown"
  : counteroffer <= mao ? "within_or_at_mao" : "above_mao";

return [{
  json: {
    ...input,
    workflow_id: "WF-337",
    controller_status: classification === "incomplete" ? "incomplete" : classification === "dnc_or_blocked" || classification === "dnc" ? "blocked" : "classified",
    response_classification: classification,
    classification_confidence: confidence,
    seller_response_text: text,
    counteroffer_amount: counteroffer,
    dynamic_mao: validMao ? mao : null,
    mao_relation: maoRelation,
    deal_id: dealId,
    lead_id: leadId,
    property_id: propertyId,
    dispatch_id: dispatchId,
    next_workflow: nextWorkflow,
    reason,
    requires_human_review: classification === "counteroffer" || classification === "price_question" || classification === "question" || classification === "accepted",
    hard_mao_guardrail: true,
    dnc_protection: true,
    idempotency_key: input.idempotency_key ?? \`wf-337:\${dispatchId ?? "unknown"}:\${classification}:\${counteroffer ?? "none"}\`
  }
}];
